import React, { useState, useEffect } from 'react';
import { api } from '../services/api';
import NewsCard from './NewsCard';
import { ThreeDots } from 'react-loader-spinner';

const Recommendations = ({ userId = 1, preferences }) => {
    const [articles, setArticles] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        fetchRecommendations();
    }, [userId, preferences]);

    const fetchRecommendations = async() => {
        try {
            setLoading(true);
            const data = await api.getRecommendations(userId);
            setArticles(data);
            setError(null);
        } catch (err) {
            setError('Failed to load recommendations');
            console.error(err);
        } finally {
            setLoading(false);
        }
    };

    if (loading) {
        return ( <
            div className = "loading-container" >
            <
            ThreeDots color = "#3b82f6"
            height = { 50 }
            width = { 50 }
            /> < /
            div >
        );
    }

    if (error) {
        return ( <
            div className = "error-container" >
            <
            p > { error } < /p> <
            button onClick = { fetchRecommendations }
            className = "btn btn-primary" >
            Try Again <
            /button> < /
            div >
        );
    }

    return ( <
            div >
            <
            h2 > 📰Recommended For You < /h2> {
            preferences && preferences.length > 0 && ( <
                div className = "preferences-summary" >
                Based on your interests: { preferences.join(', ') } <
                /div>
            )
        } <
        div className = "news-grid" > {
            articles.length > 0 ? (
                articles.map((article) => ( <
                    NewsCard key = { article.id }
                    article = { article }
                    />
                ))
            ) : ( <
                p className = "no-results" > No recommendations available.Try updating your preferences. < /p>
            )
        } <
        /div> < /
    div >
);
};

export default Recommendations;
